<?php require 'partials.php'; $uid=require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'Nytt quiz');$s=db()->prepare('INSERT INTO quizzes(user_id,title) VALUES(?,?)');$s->bind_param('is',$uid,$title);$s->execute();redirect('editor.php?id='.$s->insert_id);}
$s=db()->prepare('SELECT q.*,COUNT(qu.id) questions FROM quizzes q LEFT JOIN questions qu ON qu.quiz_id=q.id WHERE q.user_id=? GROUP BY q.id ORDER BY q.updated_at DESC');$s->bind_param('i',$uid);$s->execute();$quizzes=$s->get_result();page_top('Mina quiz'); ?>
<header class="page-head"><div><span class="eyebrow">QUIZSTUDIO</span><h1>Mina quiz</h1></div><button onclick="document.querySelector('#newQuiz').showModal()">+ Nytt quiz</button></header>
<section class="quiz-grid"><?php while($q=$quizzes->fetch_assoc()):?><article class="quiz-card"><div class="quiz-cover">⚡</div><div><small><?=$q['questions']?> frågor</small><h2><?=e($q['title'])?></h2><p><?=e($q['description'])?></p><div class="actions"><a class="button secondary" href="editor.php?id=<?=$q['id']?>">Redigera</a><a class="button" href="host.php?quiz=<?=$q['id']?>">Starta Jolt</a></div></div></article><?php endwhile?><article class="quiz-card empty" onclick="newQuiz.showModal()"><b>+</b><span>Skapa ditt första quiz</span></article></section>
<dialog id="newQuiz"><form method="post"><button type="button" class="close" onclick="newQuiz.close()">×</button><h2>Nytt quiz</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Titel</label><input name="title" required maxlength="140" autofocus><button>Skapa →</button></form></dialog>
<?php page_bottom(); ?>
